    @{ id="azurestorage"; src="https://azure.microsoft.com/en-us/blog/update-on-azure-storage-service-interruption/"; sym="azure storage bad config outage"; key="azure storage configuration outage"; pa="a bad configuration change took down the storage service"; pb="storage requests failed after an invalid configuration was applied"; pc="reverting the configuration restored storage"; pd="reverting the invalid storage configuration restored the storage service"; se="Azure 存储配置错误导致服务中断"; sf="Azure 存储配置错误导致存储服务请求大面积失败"; rc="Azure 存储配置变更错误导致服务中断"; fix="回滚配置，增加配置校验" },
    @{ id="aws2012power"; src="https://aws.amazon.com/message/67457/"; sym="us east power failure generator"; key="generator failed backup power"; pa="a power failure exposed a generator that could not carry the load"; pb="the backup generator failed when the site switched to generator power"; pc="manual power restoration and load shedding recovered the region"; pd="operators brought generators online and used load shedding to recover the region"; se="美国东部断电后备用发电机失效"; sf="市电中断切换备用电源时发电机带载失败，机房大面积断电"; rc="美国东部断电，备用发电机在带载切换时失效"; fix="修复发电机与切换逻辑，增加带载测试" },
    @{ id="aws2014tokyo"; src="https://aws.amazon.com/message/56489/"; sym="tokyo cooling control system failure"; key="cooling plc unresponsive tokyo"; pa="a datacenter control system bug made the cooling control unresponsive"; pb="the cooling units shut down and ec2 hosts overheated in one tokyo zone"; pc="manual cooling restoration and host recovery followed"; pd="operators restored cooling and brought instances back"; se="东京机房制冷控制系统故障导致服务器过热"; sf="制冷控制程序在切换时无响应，部分机组停机，服务器过热断电"; rc="第三方机房控制软件缺陷导致制冷控制无响应，东京一个可用区过热断电"; fix="修复控制软件，增加制冷失效的独立保护" }
)

if ($incidents.Count -ne 30) { throw "expected 30 incidents, got $($incidents.Count)" }

$rows = New-Object System.Collections.ArrayList
$n = 0
function Store-Case([string]$q, [string]$evalQuery, [string]$layer, [string]$rc, [string]$fix, [string]$src) {
    $script:n++
    $log = Join-Path $env:TEMP ("scx-v2-{0:D3}-{1}.log" -f $script:n, [guid]::NewGuid().ToString("N"))
    $text = ("{0}`n公开复盘, 来源: {1}`n根因: {2}" -f $q, $src, $rc)
    Write-Utf8 $log $text
    $prev = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try { $out = (& $Binary --query $q --store 1 --fix $fix --mem-dir $MemDir $log 2>&1 | Out-String) }
    finally { $ErrorActionPreference = $prev }
    if ($out -notmatch "stored case=([^\s]+) added=yes") { throw "store failed case $($script:n): $q`n$out" }
    $id = $Matches[1]
    $h = $id.Split('_')[-1]
    $note = "target=$h source=$src"
    [void]$rows.Add([pscustomobject]@{ query = $evalQuery; layer = $layer; case_id = $id; note = $note })
}

foreach ($c in $incidents) {
    Store-Case $c.sym $c.sym "literal" $c.rc $c.fix $c.src
    Store-Case $c.key $c.key "literal" $c.rc $c.fix $c.src
    Store-Case $c.pa  $c.pb  "paraphrase" $c.rc $c.fix $c.src
    Store-Case $c.pc  $c.pd  "paraphrase" $c.rc $c.fix $c.src
    Store-Case $c.se  $c.sf  "semantic" $c.rc $c.fix $c.src
}

$lines = @("query,layer,case_id,note")
foreach ($r in $rows) {
    $lines += ((@($r.query, $r.layer, $r.case_id, $r.note) | ForEach-Object { CsvField ([string]$_) }) -join ",")
}
Write-Utf8 $Csv ($lines -join "`n")

$l = @($rows | Where-Object { $_.layer -eq "literal" }).Count
$p = @($rows | Where-Object { $_.layer -eq "paraphrase" }).Count
$s = @($rows | Where-Object { $_.layer -eq "semantic" }).Count
Write-Host ("v2 corpus: total={0} literal={1} paraphrase={2} semantic={3}" -f $rows.Count, $l, $p, $s)
Write-Host "next: powershell -File scripts\real-eval-build.ps1 -Csv $Csv -Out eval-real\v2-baseline.json"
